cd <trial> && mkdir -p work && cat > work/q.tuft <<'EOF'
@h := find text "claude_matches_spec(" in "crates/" at "c568505742d00859cad758924c98d8d0a6e98648" limit 100;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)];
emit @v budget_tokens 4000;
EOF
sed -i 's/claude_matches/claim_matches/' work/q.tuft
cd work && ../../../bin/writfold tuft run q.tuft --repo <trial>/repo --state <trial>/state
